	export default {
		data() {
			return {
				type: 'office',
				activeFilter: 0,
				activeDistrict: 0,
				searchKeyword: '',
				shanghaiDistricts: ['全部', '浦东新区', '黄浦区', '徐汇区', '长宁区', '静安区', '普陀区', '虹口区', '杨浦区', '闵行区', '宝山区', '嘉定区', '松江区', '青浦区', '奉贤区', '金山区', '崇明区'],
				current: dataMap.office
			}
		},
		computed: {
			filters() { return this.current.filters },
			actionText() { return this.current.action },
			list() {
				let result = this.current.list
				// 标签筛选
				const filterTag = this.filters[this.activeFilter]
				if (filterTag && filterTag !== '全部') {
					result = result.filter(item => item.tags.indexOf(filterTag) > -1)
				}
				// 区域筛选
				const district = this.shanghaiDistricts[this.activeDistrict]
				if (district && district !== '全部') {
					result = result.filter(item => item.district === district)
				}
				// 搜索筛选
				const keyword = this.searchKeyword.trim()
				if (keyword) {
					result = result.filter(item => {
						return item.name.indexOf(keyword) > -1 || item.location.indexOf(keyword) > -1
					})
				}
				return result
			}
		},
		onLoad(options) {
			const type = options.type || 'office'
			this.type = type
			this.current = dataMap[type] || dataMap.office
			uni.setNavigationBarTitle({ title: this.current.title })
		},
		onShareAppMessage() {
			return {
				title: this.current.title + '列表',
				path: '/pages/workspace/list?type=' + this.type
			}
		},
		methods: {
			onSearch() {
				// 搜索已通过 computed list 实时过滤，此处可做额外处理
			},
			clearSearch() {
				this.searchKeyword = ''
			},
			onItem(s) { uni.showToast({ title: s.name, icon: 'none' }) },
			onContact() { uni.showToast({ title: '客服稍后联系您', icon: 'none' }) },
			onReserve() {
				uni.showModal({
					title: '预约看场',
					content: '是否预约现场看场？客服将与您确认时间。',
					confirmText: '确认预约',
					confirmColor: '#2979ff',
					success: (r) => {
						if (r.confirm) uni.showToast({ title: '预约成功', icon: 'success' })
					}
				})
			}
		}
	}
